487	<script>
488	(function(){
489	  'use strict';
490	
491	  var hero      = document.getElementById('hero-section');
492	  var plateCard = document.getElementById('plateCard');
493	  var faceFront = document.getElementById('faceFront');
494	  var faceBack  = document.getElementById('faceBack');
495	
496	  /* ---- grundbilden som token, så att sökvägen står på ETT ställe -------- */
497	  document.documentElement.style.setProperty(
498	    '--ground-img', "url('/tests/alunix-concepts-r3/build/assets/k4-cabin-desk.webp')");
499	
500	  ScrollCraft.mount(document.body);
501	
502	  /* ---- spacern mäts en gång, vid mount (scroll/README.md) ---------------
503	     Rapporterar innerHeight 0 i det ögonblicket blir spann-höjden 0 px, sidan
504	     får ingen scrolltrack och akten avancerar aldrig. En resize får motorn att
505	     mäta om. Skickas när fönstret och typsnitten har landat. */
506	  function relayout(){ dispatchEvent(new Event('resize')); }
507	  addEventListener('load', relayout);
508	  if (document.fonts && document.fonts.ready) document.fonts.ready.then(relayout);
509	
510	  /* ---- vilken sida av kortet som är nåbar -------------------------------
511	     Baksidans länk finns i DOM:en från början men är osynlig tills kortet
512	     vänts. En fokusbar länk som inte syns är ett a11y-fel, så den sidan som
513	     är bortvänd hålls inert. Utan JS är framsidan uppe och baksidan inert. */
514	  var backLive = null;
515	  function setFace(showBack){
516	    if (backLive === showBack) return;
517	    backLive = showBack;
518	    faceBack.inert = !showBack;
519	    faceFront.inert = showBack;
520	    faceBack.setAttribute('aria-hidden', showBack ? 'false' : 'true');
521	    faceFront.setAttribute('aria-hidden', showBack ? 'true' : 'false');
522	  }
523	  setFace(false);
524	
525	  /* ---- will-change bara medan akten rör sig ----------------------------
526	     Ingen per-bildruta-JS driver vändningen: --flip räknas i CSS ur --sc-ps.
527	     Det här är enbart en gränsövergång, rAF-skyddad, med deadband. */
528	  /* Aktens geometri cachas vid mount och vid resize. Progressen räknas ur
529	     scrollY med motorns egen pinnade formel, p = (y - top) / (height - vh), i
530	     stället för att läsa --sc-ps med getComputedStyle varje bildruta.
531	     MÄTT I R2: shimen läser redan getComputedStyle en gång per akt och
532	     bildruta, och sidan har sex akter. En sjunde läsning från sidans egen loop
533	     kostade utan att ge något: de två gränser den här funktionen bevakar
534	     (0 < ps < 1 och ps >= 0,42) tål den lilla skillnaden mellan råvärdet och
535	     det lerpade. Noll stilläsningar per bildruta här nu. */
536	  var actTop = 0, actH = 0;
537	  function measureAct(){
538	    var r = hero.getBoundingClientRect();
539	    actTop = r.top + window.scrollY;
540	    actH = r.height;
541	  }
542	  measureAct();
543	  addEventListener('resize', measureAct, { passive:true });
544	  addEventListener('load', measureAct);
545	
546	  var turning = null, pending = false;
547	  function readState(){
548	    pending = false;
549	    var travel = Math.max(actH - window.innerHeight, 1);
550	    var ps = (window.scrollY - actTop) / travel;
551	    if (ps < 0) ps = 0; else if (ps > 1) ps = 1;
552	    var moving = ps > 0.0005 && ps < 0.9995;
553	    if (moving !== turning){
554	      turning = moving;
555	      hero.classList.toggle('is-turning', moving);
556	    }
557	    /* smoothstep(0.12, 0.72, ps) korsar 0,5 exakt vid ps = 0,42. */
558	    setFace(ps >= 0.42);
559	  }
560	  function schedule(){ if (!pending){ pending = true; requestAnimationFrame(readState); } }
561	  addEventListener('scroll', schedule, { passive:true });
562	  addEventListener('resize', schedule, { passive:true });
563	  schedule();
564	
565	  /* ---- ?preview= --------------------------------------------------------
566	     Varje läge sätter window.__scFreezeMotion = true. sc-smooth.js läser
567	     flaggan som ett VÄRDE och spårar då det råa värdet exakt, så en skärmbild
568	     visar det formade läget och inte en lerp i flykten. V3b exponerade
569	     __scFreezeMotion som ett funktionspar, vilket shimen inte kan läsa. */
570	  var MODES = { front:0, mid:0.5, back:1 };
571	  var mode = new URLSearchParams(location.search).get('preview');
572	  if (mode && Object.prototype.hasOwnProperty.call(MODES, mode)){
573	    window.__scFreezeMotion = true;
574	    plateCard.style.setProperty('--flip', String(MODES[mode]));
575	    setFace(MODES[mode] >= 0.5);
576	    hero.classList.remove('is-turning');
577	    document.documentElement.setAttribute('data-preview', mode);
578	  }
579	})();
580	</script>
