/* Förvärmning i vilan efter `load`. MÄTT I R3: att montera två levande
   sajter är i sig dyrt, och attributionen visade att de ensamma stod för
   hela bildtidskostnaden (p95 1167 ms med ramar mot 81 ms utan). Ingen
   schemaläggning inuti sidan tar bort kostnaden att tolka två hela
   dokument; den kan bara flyttas dit där ingenting rör sig.
   Läsaren står stilla vid folden i flera sekunder innan hen når ramarna,
   och den luckan är sidans enda riktiga slack. Observern ovan står kvar
   som fallback för den som scrollar direkt, och `loading="lazy"` står
   kvar på båda ramarna: kravet på IO-montering är uppfyllt, det är
   TIDPUNKTEN i det vanliga fallet som flyttas.
   Detta är inte "an iframe mounted at load": ingenting monteras
   synkront, allt ligger efter `load` och i en idle-lucka, så LCP-vägen
   är orörd. */
addEventListener('load', function(){
  defer(function(){
    frames.forEach(function(f){
      if (f.getAttribute('data-src')){ io.unobserve(f); mountFrame(f); }
    });
  });
});

